/* Risk Alert filter
   Keeps only HIGH / CRITICAL courses from the Academic Analyst Agent and
   attaches the student's name + email, which "Get student" already read from
   the Students sheet at the start of this execution.

   Returning [] stops the branch, so no email is sent when nothing is at risk.
   We deliberately do NOT add a second Google Sheets read here: a Sheets node
   placed after a multi-item node runs once per item and returns the whole tab
   each time (HANDOFF trap 8). */

const analysis = $input.first().json.output || {};
const courses  = (analysis.courses || []).filter(
  c => c.risk_level === 'HIGH' || c.risk_level === 'CRITICAL'
);

if (!courses.length) return [];

const student = $('Get student').first().json || {};
const email   = String(student.email || '').trim();

if (!email) return [];

return courses
  .sort((a, b) => (a.priority || 99) - (b.priority || 99))
  .map(c => ({
    json: {
      student_id:    analysis.student_id || student.student_id || '',
      student_name:  student.name || 'there',
      student_email: email,
      course_name:   c.course_name || 'your course',
      risk_level:    c.risk_level,
      reason:        c.reason || 'No reason was returned by the analyst.',
      recommended_weekly_hours: c.recommended_weekly_hours ?? 0,
      focus: Array.isArray(c.focus) ? c.focus.join(', ') : String(c.focus || ''),
    },
  }));
